module logic;
use model {Hit,Search};
use util {reverse};
fn run(text:Text,needle:Text,start:I64)->Search<Hit> {
 let text_length=Text::length(text);
 let needle_length=Text::length(needle);
 if start<0 || start>text_length {Invalid(start)} else {
  let index=while(i:I64=start;i<text_length && needle_length<=text_length-i && Text::slice(text,i,needle_length)!=needle) {i+1};
  if index<=text_length && needle_length<=text_length-index {
   let end=index+needle_length;
   Found(Hit {index:index,prefix:Text::slice(text,0,index),suffix:Text::slice(text,end,text_length-end),match_bytes:Bytes::length(Text::bytes(needle))})
  } else {Missing}
 }
}

